draw((4*i,0)--(4*i,16),blue+linewidth(2));
draw((0,4*i)--(16,4*i),blue+linewidth(2));
}
for (int i = 0; i <= 3; ++i) {
label(" $R$ ", (4*i+0.5,i+0.5),fontsize(16pt));
label(" $R$ ", (4*i+1.5,i+4.5),fontsize(16pt));
label(" $R$ ", (4*i+2.5,i+8.5),fontsize(16pt));
label(" $R$ ", (4*i+3.5,i+12.5),fontsize(16pt));
