\begin{align*}
(1+n^{-1})^n &= \sum_{j=0}^n\binom{n}j n^{-j}
&= 1+\binom{n}1 n^{-1} + \sum_{j=2}^n\binom{n}j n^{-j}
&= 2 + \sum_{j=2}^n \frac1{j!} \frac{ \prod_{k=0}^{j-1} (n-k)}{n^j}
&\leq 2 + \sum_{j=2}^n \frac1{j!}
&\leq 2 + \sum_{j=2}^n \frac1{j(j-1)}
&= 2 + \sum_{j=2}^n\left( \frac1{j-1} - \frac1j\right)
&= 3 - \frac1n < 3
\end{align*}

