 $\boxed{\text{Problem 1}}$ Firstly we evaluate sums:
\begin{align*}
\sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k+1}{n}} &= \sum_{k=0}^{n-1} \left(  1 - a^{-\frac{1}{n}} \right) = n \left( 1-\sqrt[n]{\frac{1}{a}} \right) 
\sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k}{n}} &= \sum_{k=0}^{n-1} \left(  a^{\frac{1}{n}} - 1 \right)  = n \left( \sqrt[n]{a}-1 \right). 
\end{align*}

We can write initial inequality in the form
\begin{align*}
n \left( 1-\sqrt[n]{\frac{1}{a}} \right)  < \ln a < n \left( \sqrt[n]{a}-1 \right) .
\end{align*}
I put  $ \sqrt[n]{\frac{1}{a}} = y \rightarrow n = -\frac{\ln a}{\ln y}$  (note that  $0<y<1$ ) then we have:
\begin{align*}
-\frac{\ln a}{\ln y} \left( 1-y \right)  &< \ln a < -\frac{\ln a}{\ln y} \left( \frac{1}{y^n}-1 \right) 
 y-1  &> \ln y > 1- \frac{1}{y} . 
\end{align*}
Inequality  $y-1  > \ln y $  obviously holds.
\begin{align*}
  \ln y &> 1- \frac{1}{y}  
 y\ln y-y+1&> 0 , 
\end{align*}
which is also true (maybe not so obviously, but derivative will show it). So we  $\underline{\text{proved}}$  relation
\begin{align*}
 \sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k+1}{n}} < \int_1^a \frac{1}{x}\ dx <\sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k}{n}} .
\end{align*} $\boxed{\text{Problem 2}}$ We evaluate limits of sums:
\begin{align*}
\lim_{n\to \infty} \sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k+1}{n}} &=\lim_{n\to \infty}   n \left( 1-\sqrt[n]{\frac{1}{a}} \right)  = \lim_{y\to 1}  -\frac{\ln a}{\ln y}(1-y)=
& = \ln a \cdot \lim_{y\to 1}  \frac{y-1}{\ln y} = \ln a \cdot \lim_{y\to 1} y  = \ln a. 
\end{align*}

\begin{align*}
\lim_{n\to \infty} \sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k}{n}} &=\lim_{n\to \infty} n \left( \sqrt[n]{a}-1 \right) =-\ln a \cdot \lim_{y\to 1} \frac{\frac{1}{y}-1}{\ln y} =
&=-\ln a \cdot \lim_{y\to 1} -\frac{1}{y} = \ln a.
\end{align*}

So we  $\underline{\text{proved}}$ \begin{align*}
\lim_{n\to \infty}  \sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k+1}{n}} = \int_1^a \frac{1}{x}\ dx =\lim_{n\to \infty}  \sum_{k=0}^{n-1} \left(  a^{\frac{k+1}{n}} - a^{\frac{k}{n}} \right) \cdot a^{-\frac{k}{n}}.
\end{align*}
